"""Evaluation helpers. Labels are always the SECOND argument so they can only
be consumed after scores exist (R9, R10)."""
from __future__ import annotations

import numpy as np
from sklearn.metrics import (
    average_precision_score,
    precision_recall_curve,
    roc_auc_score,
)

__all__ = ["auc_roc", "auc_pr", "auc_pr_trapezoid", "summarize"]


def auc_roc(y: np.ndarray, scores: np.ndarray) -> float:
    """AUC-ROC (R9)."""
    return float(roc_auc_score(y, scores))


def auc_pr(y: np.ndarray, scores: np.ndarray) -> float:
    """AUC-PR as average precision (sklearn convention, R9)."""
    return float(average_precision_score(y, scores))


def auc_pr_trapezoid(y: np.ndarray, scores: np.ndarray) -> float:
    """AUC-PR via the trapezoidal rule on the precision-recall curve."""
    precision, recall, _ = precision_recall_curve(y, scores)
    return float(-np.trapz(precision, recall))


def summarize(values) -> dict:
    """mean / std / min / max over repeats (R8)."""
    v = np.asarray(list(values), dtype=np.float64)
    return {
        "mean": float(v.mean()),
        "std": float(v.std(ddof=0)),
        "std_ddof1": float(v.std(ddof=1)),
        "min": float(v.min()),
        "max": float(v.max()),
        "n": int(v.size),
        "values": [float(x) for x in v],
    }

